import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            K = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
        except StopIteration:
            break

        if K == 1:
            is_palindrome = True
            for i in range(N // 2):
                if A[i] != A[N - 1 - i]:
                    is_palindrome = False
                    break
            if is_palindrome:
                results.append("YES")
            else:
                results.append("NO")
        else:
            can_make_palindrome = True
            for i in range(N // 2): left_val = A[i]
                right_val = A[N - 1 - i]
                if left_val != right_val:
                    can_make_palindrome = False
                    break
            if can_make_palindrome:
                results.append("YES")
            else:
                 results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
